  // guide tab
  "guide.title": "HoneyMoney — Guide",
  "guide.subtitle": "Funding transparency, spending autonomy — one money engine for individuals, couples and families.",
  "guide.install.title": "Install on your phone",
  "guide.install.body": "Add HoneyMoney to your home screen — it works offline, no app store. On Android, open the ☰ menu → “Install app” for a one-tap install. On iPhone / iPad, Apple only allows it through Safari:",
  "guide.ai.title": "The AI — what it does (and doesn’t)",
  "guide.ai.intro": "AI is optional. The app runs at RM 0 with no key at all — receipt scanning works on your device. Turn AI on and capture becomes an assistant that reasons over your own money graph, not a generic chatbot: it always proposes, you confirm, and nothing is saved until you say so.",
  "guide.ai.1.label": "Reads a receipt in the context of your history",
  "guide.ai.1.body": "Forward a photo or e-wallet screenshot — Honey reads the amount, merchant and date, files it into the bucket you usually use for that merchant, flags a likely duplicate (the “same receipt sent by both partners” trap), and notices a subscription or an amount unusual for you — measured against your own past, not a stranger’s average.",
  "guide.ai.2.label": "Forward-looking, never a scold",
  "guide.ai.2.body": "Honey’s insight looks at where the month is heading — e.g. “at this pace your Savings goal slips about six weeks” — and offers a rebalance you can take or ignore. It talks about the plan, not your personal spending, and never itemises Bucket 3.",
  "guide.ai.3.label": "Works offline, costs nothing",
  "guide.ai.3.body": "Receipt scanning runs on your device with no tokens. Add a free key (Groq · Gemini · Ollama) only if you want the smarter, graph-grounded reading.",
  "guide.ai.4.label": "You stay in control",
  "guide.ai.4.body": "The AI proposes; you confirm or correct. Your correction is what gets saved, and every change is written to a tamper-evident audit trail.",
  "guide.ai.setupLink": "Set it up →",
  "guide.ai.note": "Honey is educational, not financial advice — see the disclaimer below.",
  "guide.howto.title": "How to use it",
  "guide.howto.1.label": "Pick a persona",
  "guide.howto.1.body": "the switcher at the top of",
  "guide.howto.1.body2": "flips between one person, a couple and a family. Same engine, same three buckets — only the household changes size.",
  "guide.howto.2.label": "Read the money as a picture",
  "guide.howto.2.body": "six views over the same data:",
  "guide.howto.2.sankeyDesc": "flow of every ringgit",
  "guide.howto.2.treemapDesc": "where the budget sits",
  "guide.howto.2.networkLabel": "network",
  "guide.howto.2.barsLabel": "bars",
  "guide.howto.2.and": "and",
  "guide.howto.3.label": "Focus a lens",
  "guide.howto.3.body": "slice everything by an income stream, a bucket/expense, a category, or a",
  "guide.howto.3.person": "person",
  "guide.howto.3.body2": "(their spend only). One click to clear.",
  "guide.howto.4.label": "Add anything",
  "guide.howto.4.addPanel": "Add to the graph",
  "guide.howto.4.body": "panel adds a spend, an income stream, a bucket/department, or an allocation. For a spend you can",
  "guide.howto.4.type": "type it or",
  "guide.howto.4.scan": "scan a receipt",
  "guide.howto.4.body2": "both run on your device, free, with no AI tokens.",
  "guide.howto.5.label": "The 3 buckets",
  "guide.howto.5.body": "money splits into",
  "guide.howto.5.needs": "Must-paid",
  "guide.howto.5.savings": "Savings",
  "guide.howto.5.shield": "(your future shield), and",
  "guide.howto.5.personal": "Spendings",
  "guide.howto.5.body2": "— the Spendings bucket is",
  "guide.howto.5.notItemized": "not itemized",
  "guide.howto.5.body3": ", by design.",
  "guide.privacy.title": "Your privacy",
  "guide.privacy.1.label": "Private by design.",
  "guide.privacy.1.body": "The demo runs on a local database on the operator's machine — your household data does not need to leave it.",
  "guide.privacy.2.label": "Screenshots are read, not kept.",
  "guide.privacy.2.body": "When a receipt is parsed, we store the structured fields (vendor, amount, date) —",
  "guide.privacy.2.not": "not",
  "guide.privacy.2.body2": "the raw image.",
  "guide.privacy.3.label": "On-device capture sends nothing.",
  "guide.privacy.3.body": "Receipt scanning runs in your browser — nothing is sent anywhere to read it. Attach the photo to a record and it is stored with that record; you can delete it any time.",
  "guide.privacy.4.label": "Personal wallets stay private.",
  "guide.privacy.4.body": "Bucket-3 spending is not itemized — autonomy over surveillance.",
  "guide.privacy.5.label": "You control the data.",
  "guide.privacy.5.body": "Add or remove people any time; removing someone keeps past spend but un-attributes it. No ads. We do not sell your data.",
  "guide.privacy.6.label": "Optional AI is minimal.",
  "guide.privacy.6.body": "If the AI insight is enabled, it receives a short summary of your budget status — never your raw transactions or identity.",
  "guide.disclaimer.title": "Disclaimer",
  "guide.disclaimer.1.label": "Not financial advice.",
  "guide.disclaimer.1.body": "HoneyMoney is an informational budgeting & insight tool, not a licensed financial adviser. For personal advice, consult a licensed financial planner or, in Malaysia,",
  "guide.disclaimer.1.body2": "(free credit counselling).",
  "guide.disclaimer.2.label": "Not a bank.",
  "guide.disclaimer.2.body": "HoneyMoney does not hold, move, or invest your money. It only helps you see and plan it. Any savings/investment products mentioned belong to their licensed providers.",
  "guide.disclaimer.3.label": "Figures are estimates.",
  "guide.disclaimer.3.body": "Projections extrapolate from what you enter; they are planning aids, not guarantees. Always verify against your bank/e-wallet statements.",
  "guide.disclaimer.4.label": "Demo data is synthetic.",
  "guide.disclaimer.4.body": "The Rahman family, Nadia & Faiz, and Aisha are illustrative — any resemblance to real people is coincidental.",
  "guide.disclaimer.5.label": "Compliance is yours.",
  "guide.disclaimer.5.body": "Statutory items (EPF/SOCSO/EIS, PCB, SST) are shown as cashflow, not as a filing. File returns through LHDN/KWSP or your accountant.",
  "guide.contact": "Questions or a data request? Contact whoever set up this instance. See also the AI use disclosure in the project's",
