  // guide tab
  "guide.title": "HoneyMoney — Panduan",
  "guide.subtitle": "Ketelusan pendanaan, autonomi perbelanjaan — satu enjin wang untuk peribadi, keluarga dan perniagaan.",
  "guide.install.title": "Pasang pada telefon anda",
  "guide.install.body": "Tambah HoneyMoney ke skrin utama — berfungsi luar talian, tiada gedung aplikasi. Pada Android, buka menu ☰ → “Pasang apl” untuk pemasangan satu ketikan. Pada iPhone / iPad, Apple hanya membenarkannya melalui Safari:",
  "guide.ai.title": "AI — apa yang ia buat (dan tidak buat)",
  "guide.ai.intro": "AI adalah pilihan. Aplikasi berjalan pada RM 0 tanpa sebarang kunci — imbasan resit berfungsi pada peranti anda. Hidupkan AI dan tangkapan menjadi pembantu yang menaakul pada graf wang anda sendiri, bukan chatbot biasa: ia sentiasa mencadang, anda mengesahkan, dan tiada apa disimpan sehingga anda benarkan.",
  "guide.ai.1.label": "Membaca resit mengikut konteks sejarah anda",
  "guide.ai.1.body": "Kirim foto atau tangkapan skrin e-dompet — Honey membaca jumlah, kedai dan tarikh, memfailkannya ke baldi yang biasa anda guna untuk kedai itu, menandakan pendua berkemungkinan (masalah “resit sama dihantar oleh kedua-dua pasangan”), dan mengesan langganan atau jumlah luar biasa bagi anda — berbanding sejarah anda sendiri, bukan purata orang lain.",
  "guide.ai.2.label": "Memandang ke hadapan, bukan menegur",
  "guide.ai.2.body": "Pandangan Honey melihat ke mana arah bulan ini — cth. “pada kadar ini matlamat Simpanan anda tergelincir kira-kira enam minggu” — dan menawarkan imbangan semula yang boleh anda ambil atau abaikan. Ia bercakap tentang rancangan, bukan perbelanjaan peribadi anda, dan tidak sekali-kali memperincikan Baldi 3.",
  "guide.ai.3.label": "Berfungsi luar talian, tanpa kos",
  "guide.ai.3.body": "Imbasan resit berjalan pada peranti anda tanpa token. Tambah kunci percuma (Groq · Gemini · Ollama) hanya jika anda mahu pembacaan lebih pintar yang berasaskan graf.",
  "guide.ai.4.label": "Anda kekal mengawal",
  "guide.ai.4.body": "AI mencadang; anda mengesahkan atau membetulkan. Pembetulan anda yang disimpan, dan setiap perubahan ditulis ke jejak audit yang kalis usik.",
  "guide.ai.setupLink": "Sediakannya →",
  "guide.ai.note": "Honey bersifat pendidikan, bukan nasihat kewangan — lihat penafian di bawah.",
  "guide.howto.title": "Cara menggunakannya",
  "guide.howto.1.label": "Pilih persona",
  "guide.howto.1.body": "penukar di bahagian atas",
  "guide.howto.1.body2": "bertukar antara isi rumah, perniagaan, atau individu sendirian. Enjin yang sama, label yang berbeza.",
  "guide.howto.2.label": "Baca wang sebagai gambar",
  "guide.howto.2.body": "enam paparan atas data yang sama:",
  "guide.howto.2.sankeyDesc": "aliran setiap ringgit",
  "guide.howto.2.treemapDesc": "di mana bajet berada",
