  "guide.privacy.title": "Privasi anda",
  "guide.privacy.1.label": "Privasi secara lalai.",
  "guide.privacy.1.body": "Demo ini berjalan pada pangkalan data tempatan di mesin operator — data isi rumah anda tidak perlu meninggalkannya.",
  "guide.privacy.2.label": "Tangkapan skrin dibaca, bukan disimpan.",
  "guide.privacy.2.body": "Apabila resit dihuraikan, kami menyimpan medan berstruktur (vendor, jumlah, tarikh) —",
  "guide.privacy.2.not": "bukan",
  "guide.privacy.2.body2": "imej mentah.",
  "guide.privacy.3.label": "Tangkapan pada peranti tidak menghantar apa-apa.",
  "guide.privacy.3.body": "Imbasan resit berjalan dalam pelayar anda — tiada apa dihantar ke mana-mana untuk membacanya. Jika anda lampirkan foto pada rekod, ia disimpan bersama rekod itu; anda boleh memadamnya bila-bila masa.",
  "guide.privacy.4.label": "Dompet peribadi kekal peribadi.",
  "guide.privacy.4.body": "Perbelanjaan Baldi-3 tidak diperincikan — autonomi mengatasi pengawasan.",
  "guide.privacy.5.label": "Anda mengawal data.",
  "guide.privacy.5.body": "Tambah atau buang orang bila-bila masa; membuang seseorang mengekalkan perbelanjaan lampau tetapi menyahkaitkannya. Tiada iklan. Kami tidak menjual data anda.",
  "guide.privacy.6.label": "AI pilihan adalah minimum.",
  "guide.privacy.6.body": "Jika wawasan AI didayakan, ia menerima ringkasan pendek status bajet anda — tidak pernah transaksi mentah atau identiti anda.",
  "guide.disclaimer.title": "Penafian",
  "guide.disclaimer.1.label": "Bukan nasihat kewangan.",
  "guide.disclaimer.1.body": "HoneyMoney ialah alat belanjawan & wawasan bermaklumat, bukan penasihat kewangan berlesen. Untuk nasihat peribadi, rujuk perancang kewangan berlesen atau, di Malaysia,",
  "guide.disclaimer.1.body2": "(kaunseling kredit percuma).",
  "guide.disclaimer.2.label": "Bukan bank.",
  "guide.disclaimer.2.body": "HoneyMoney tidak memegang, memindahkan, atau melabur wang anda. Ia hanya membantu anda melihat dan merancangnya. Sebarang produk simpanan/pelaburan yang disebut adalah milik penyedia berlesen masing-masing.",
  "guide.disclaimer.3.label": "Angka adalah anggaran.",
  "guide.disclaimer.3.body": "Unjuran diekstrapolasi daripada apa yang anda masukkan; ia adalah alat bantu perancangan, bukan jaminan. Sentiasa sahkan dengan penyata bank/e-dompet anda.",
  "guide.disclaimer.4.label": "Data demo adalah sintetik.",
  "guide.disclaimer.4.body": "Isi rumah Rahman, kafe itu, dan Aisha adalah ilustrasi — sebarang persamaan dengan orang atau perniagaan sebenar adalah kebetulan.",
  "guide.disclaimer.5.label": "Pematuhan adalah tanggungjawab anda.",
  "guide.disclaimer.5.body": "Untuk kegunaan perniagaan (cukai, EPF/SOCSO/EIS, SST, e-Invois LHDN), HoneyMoney ialah lensa aliran tunai — failkan penyata berkanun melalui akauntan anda atau perisian yang diluluskan.",
  "guide.contact": "Soalan atau permintaan data? Hubungi operator isi rumah/perniagaan yang menyediakan instance ini. Lihat juga pendedahan penggunaan AI dalam projek",
