  "guide.privacy.1.label": "डिफ़ॉल्ट रूप से निजता।",
  "guide.privacy.1.body": "डेमो ऑपरेटर की मशीन पर एक लोकल डेटाबेस पर चलता है — आपके परिवार के डेटा को इसे छोड़ने की ज़रूरत नहीं।",
  "guide.privacy.2.label": "स्क्रीनशॉट पढ़े जाते हैं, रखे नहीं जाते।",
  "guide.privacy.2.body": "जब कोई रसीद पार्स होती है, तो हम संरचित फ़ील्ड (विक्रेता, राशि, तारीख) संग्रहीत करते हैं —",
  "guide.privacy.2.not": "नहीं",
  "guide.privacy.2.body2": "कच्ची इमेज।",
  "guide.privacy.3.label": "डिवाइस पर कैप्चर कुछ नहीं भेजता।",
  "guide.privacy.3.body": "रसीद स्कैनिंग आपके ब्राउज़र में चलती है — पढ़ने के लिए कुछ भी कहीं नहीं भेजा जाता। फोटो को रिकॉर्ड से जोड़ें तो वह उसी रिकॉर्ड के साथ सहेजी जाती है; आप उसे कभी भी हटा सकते हैं।",
  "guide.privacy.4.label": "निजी वॉलेट निजी रहते हैं।",
  "guide.privacy.4.body": "बकेट-3 का खर्च विस्तृत नहीं होता — निगरानी पर स्वायत्तता।",
  "guide.privacy.5.label": "डेटा पर आपका नियंत्रण है।",
  "guide.privacy.5.body": "किसी भी समय लोग जोड़ें या हटाएँ; किसी को हटाने पर पिछला खर्च बना रहता है पर उसका श्रेय हट जाता है। कोई विज्ञापन नहीं। हम आपका डेटा नहीं बेचते।",
  "guide.privacy.6.label": "वैकल्पिक AI न्यूनतम है।",
  "guide.privacy.6.body": "अगर AI इनसाइट चालू है, तो उसे आपके बजट की स्थिति का एक छोटा सारांश मिलता है — कभी आपके कच्चे लेन-देन या पहचान नहीं।",
  "guide.disclaimer.title": "अस्वीकरण",
  "guide.disclaimer.1.label": "वित्तीय सलाह नहीं।",
  "guide.disclaimer.1.body": "HoneyMoney एक जानकारीपूर्ण बजटिंग और इनसाइट टूल है, कोई लाइसेंस-प्राप्त वित्तीय सलाहकार नहीं। निजी सलाह के लिए, किसी लाइसेंस-प्राप्त वित्तीय योजनाकार से, या मलेशिया में,",
  "guide.disclaimer.1.body2": "(मुफ़्त क्रेडिट काउंसलिंग) से सलाह लें।",
  "guide.disclaimer.2.label": "बैंक नहीं।",
  "guide.disclaimer.2.body": "HoneyMoney आपका पैसा न रखता है, न भेजता है, न निवेश करता है। यह सिर्फ़ आपको इसे देखने और योजना बनाने में मदद करता है। बताए गए कोई भी बचत/निवेश उत्पाद उनके लाइसेंस-प्राप्त प्रदाताओं के हैं।",
  "guide.disclaimer.3.label": "आँकड़े अनुमान हैं।",
  "guide.disclaimer.3.body": "अनुमान आपके दर्ज किए गए डेटा से निकाले जाते हैं; ये योजना में सहायक हैं, गारंटी नहीं। हमेशा अपने बैंक/ई-वॉलेट विवरण से मिलान करें।",
  "guide.disclaimer.4.label": "डेमो डेटा काल्पनिक है।",
  "guide.disclaimer.4.body": "रहमान परिवार, कैफ़े, और आइशा उदाहरण मात्र हैं — किसी वास्तविक व्यक्ति या बिज़नेस से समानता संयोग है।",
  "guide.disclaimer.5.label": "अनुपालन आपकी ज़िम्मेदारी है।",
  "guide.disclaimer.5.body": "बिज़नेस उपयोग (टैक्स, EPF/SOCSO/EIS, SST, LHDN e-Invoicing) के लिए, HoneyMoney एक कैशफ़्लो लेंस है — वैधानिक रिटर्न अपने अकाउंटेंट या मान्यता-प्राप्त सॉफ़्टवेयर के ज़रिए दाखिल करें।",
  "guide.contact": "सवाल या डेटा का अनुरोध? इस इंस्टेंस को सेट करने वाले परिवार/बिज़नेस ऑपरेटर से संपर्क करें। प्रोजेक्ट के इसमें AI उपयोग का खुलासा भी देखें",
  "g.caption.sankey": "हर रिंगिट, ट्रेस किया गया: आय बकेट में बँटती है, फिर असल खर्च (लाल) बनाम जो बचा रहता है (हरा) में। रिबन की चौड़ाई ∝ RM।",
  "g.caption.treemap": "एक नज़र में बजट संरचना: सेल का क्षेत्रफल ∝ मासिक आवंटन, रंग ∝ स्थिति, और ठोस भराव अनुमानित खर्च के साथ बढ़ता है।",
  "g.caption.tree": "परिवार का बजट एक शाखाओं वाली संरचना के रूप में — खर्च स्तर → बकेट → विक्रेता। किसी नोड पर होवर कर उसकी वंशावली ट्रेस करें।",
  "g.caption.organic": "कच्चा नॉलेज ग्राफ़, बल-शिथिल। नोड का आकार ∝ कनेक्शन; किसी नोड और उसके पड़ोसियों पर फोकस के लिए होवर करें।",
  "g.caption.bars": "बजट बनाम वास्तविक, एक ही साझा RM पैमाने पर, ताकि हर बकेट सीधे तुलना योग्य हो। बिंदुदार रेखा = आवंटन की सीमा।",
  "g.caption.flow": "क्लासिक शाखा दृश्य — बाईं ओर खर्च, बीच में परिवार की संरचना, दाईं ओर आय।",
