  "imp.privacy": "आपका स्टेटमेंट इसी मशीन पर पढ़ा जाता है और कभी संग्रहीत नहीं होता। केवल वही पंक्तियाँ रिकॉर्ड बनती हैं जिन्हें आप चुनते हैं — और हर एक को बाद में सुधारा या हटाया जा सकता है, बदलाव ऑडिट ट्रेल में रहता है।",
