  "try.honey.spendings": "日常開銷是你自己的。HoneyMoney 只記錄總額，到此為止 — 絕不向家裡其他人逐筆列出這一籃。",
  "try.honey.income": "收入不屬於任何帳戶籃 — 它來自家庭以外，由你的分配規則決定去向。在這裡記錄，也是在告訴儀表板、H-Score 和 Honey 你賺多少。",
